    ctx.textBaseline = 'middle'; ctx.textAlign = 'left'; ctx.fillStyle = color;
    const main = `500 ${size}px ${FAM.mono}`, ital = `italic 600 ${size * 1.05}px ${FAM.body}`, sub = `600 ${size * 0.62}px ${FAM.body}`;
