    ctx.globalAlpha *= o.alpha === undefined ? 1 : o.alpha;
    ctx.strokeStyle = o.color || C.dim; ctx.lineWidth = o.w || 3; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
