      y: seg(lt, 6.0, 6.5), encY: seg(lt, 6.2, 6.7), sy: seg(lt, 6.5, 7.0), target: seg(lt, 7.0, 7.4),
      pred: seg(lt, 8.0, 8.5), shat: seg(lt, 9.0, 9.5), z: seg(lt, 9.3, 9.8),
